-- Step 7: goal tracking and auditable report exports. Report facts remain in normalized ledgers.
create table if not exists public.crm_goals(company_state_id text not null default public.crm_base_state_id(),id text not null,name text not null,metric text not null check(metric in ('sold_revenue','collected_revenue','gross_profit','new_leads','won_jobs','estimates_sent')),target_amount numeric(14,2) not null default 0,target_count integer not null default 0 check(target_count>=0),period_start date not null,period_end date not null check(period_end>=period_start),assigned_user_id uuid,status text not null default 'active' check(status in ('active','achieved','closed')),created_by uuid not null default auth.uid(),updated_by uuid not null default auth.uid(),created_at timestamptz not null default clock_timestamp(),updated_at timestamptz not null default clock_timestamp(),primary key(company_state_id,id));
create table if not exists public.crm_report_exports(company_state_id text not null default public.crm_base_state_id(),id text not null,report_type text not null,filters jsonb not null default '{}'::jsonb,row_count integer not null default 0 check(row_count>=0),requested_by uuid not null default auth.uid(),created_at timestamptz not null default clock_timestamp(),primary key(company_state_id,id));
create index if not exists crm_goals_period_idx on public.crm_goals(company_state_id,status,period_start,period_end);
alter table public.crm_goals enable row level security;alter table public.crm_report_exports enable row level security;
revoke all on public.crm_goals from public,anon,authenticated;revoke all on public.crm_report_exports from public,anon,authenticated;
drop policy if exists "CRM users read goals" on public.crm_goals;drop policy if exists "CRM managers insert goals" on public.crm_goals;drop policy if exists "CRM managers update goals" on public.crm_goals;
create policy "CRM users read goals" on public.crm_goals for select to authenticated using(public.is_coastal_crest_user() and company_state_id=public.crm_base_state_id() and (assigned_user_id is null or assigned_user_id=(select auth.uid()) or public.can_manage_team_crm()));
create policy "CRM managers insert goals" on public.crm_goals for insert to authenticated with check(public.can_manage_team_crm() and company_state_id=public.crm_base_state_id() and created_by=(select auth.uid()));
create policy "CRM managers update goals" on public.crm_goals for update to authenticated using(public.can_manage_team_crm() and company_state_id=public.crm_base_state_id()) with check(public.can_manage_team_crm() and company_state_id=public.crm_base_state_id());
grant select,insert,update on public.crm_goals to authenticated;
drop policy if exists "CRM users read own report exports" on public.crm_report_exports;drop policy if exists "CRM users create report exports" on public.crm_report_exports;
create policy "CRM users read own report exports" on public.crm_report_exports for select to authenticated using(company_state_id=public.crm_base_state_id() and (requested_by=(select auth.uid()) or public.can_manage_team_crm()));
create policy "CRM users create report exports" on public.crm_report_exports for insert to authenticated with check(public.is_coastal_crest_user() and company_state_id=public.crm_base_state_id() and requested_by=(select auth.uid()));
grant select,insert on public.crm_report_exports to authenticated;
